import{_ as a,o,c as t,a2 as r}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"End-to-End Feature Workflow","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/end-to-end-features.md","filePath":"develop/end-to-end-features.md","lastUpdated":null}'),i={name:"develop/end-to-end-features.md"};function n(s,e,d,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/end-to-end-features.md" target="_blank" rel="noreferrer"><code>.agents/end-to-end-features.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="end-to-end-feature-workflow" tabindex="-1">End-to-End Feature Workflow <a class="header-anchor" href="#end-to-end-feature-workflow" aria-label="Permalink to &quot;End-to-End Feature Workflow&quot;">​</a></h1><p>Use this when implementing a feature that spans data model, shared domain contracts, API, and web UI.</p><p>This file defines implementation order. For package-specific rules, follow the linked docs instead of repeating them here.</p><p>When a feature introduces shared contracts that should drive both API and frontend behavior, this workflow also includes <code>packages/core</code>.</p><h2 id="default-order" tabindex="-1">Default Order <a class="header-anchor" href="#default-order" aria-label="Permalink to &quot;Default Order&quot;">​</a></h2><ol><li>If the feature needs new data or persisted fields, update <code>packages/db</code> first.</li><li>If the feature introduces shared enums, schemas, formatters, or defaults consumed across packages, update <code>packages/core</code> next.</li><li>Put reusable server-side domain workflows in <code>packages/app</code> when both inline API fallback and workers need them.</li><li>Add queue contracts, dispatch, processors, schedules, or retention orchestration in <code>packages/jobs</code> when work is asynchronous.</li><li>Define or extend the oRPC contract in <code>packages/api</code>.</li><li>Add slice-local TanStack Query wrappers in <code>apps/web</code>.</li><li>Handle user-visible client errors using the typed oRPC client pattern.</li><li>Wire route preloading, guards, and UI composition in <code>apps/web</code>.</li><li>Run fixes and relevant validation according to <a href="/SaaSWeave/develop/workflow">Workflow</a>, using <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/choice-flows.md" target="_blank" rel="noreferrer">Choice flows</a> only when a human decision is needed.</li></ol><h2 id="step-1-database" tabindex="-1">Step 1: Database <a class="header-anchor" href="#step-1-database" aria-label="Permalink to &quot;Step 1: Database&quot;">​</a></h2><ul><li>Edit schemas in <code>packages/db/src/schema/</code> when the feature changes persisted data.</li><li>Follow <a href="/SaaSWeave/develop/workflow">Workflow</a> for migration generation, localhost <code>DATABASE_URL</code> safety, and migration application.</li><li>Keep schema and migration work complete before defining API output shapes that depend on it.</li></ul><h2 id="step-2-shared-domain-contract" tabindex="-1">Step 2: Shared Domain Contract <a class="header-anchor" href="#step-2-shared-domain-contract" aria-label="Permalink to &quot;Step 2: Shared Domain Contract&quot;">​</a></h2><ul><li>Use <code>packages/core</code> for shared Zod schemas, enums, normalizers, formatters, option builders, and defaults consumed by more than one package.</li><li>Follow <a href="/SaaSWeave/develop/core">Core package patterns</a>.</li><li>Unless explicitly told not to, if a change should propagate automatically into both API and frontend behavior, centralize it in <code>packages/core</code> instead of duplicating literals in app code.</li><li>Route validators, frontend filters, and shared API input or output schemas should import core contracts when they represent the same domain surface.</li></ul><h2 id="step-3-api-contract" tabindex="-1">Step 3: API Contract <a class="header-anchor" href="#step-3-api-contract" aria-label="Permalink to &quot;Step 3: API Contract&quot;">​</a></h2><p>Before transport work, decide whether server-side behavior belongs in an application service or a job:</p><ul><li><p>Use <code>packages/app</code> for worker-safe domain services with DB/storage/provider side effects but no oRPC or BullMQ registration.</p></li><li><p>Use <code>packages/jobs</code> for queue payloads, enqueue helpers, processors, repeatable schedules, and post-domain orchestration such as notifications.</p></li><li><p>Keep <code>apps/worker</code> limited to process startup/shutdown, readiness, metrics, signals, and <code>createAllWorkers()</code> composition.</p></li><li><p>Add or extend the router in <code>packages/api</code>.</p></li><li><p>Follow <a href="/SaaSWeave/develop/orpc">oRPC patterns</a> for procedure factories, explicit <code>input</code> and <code>output</code> schemas, and typed errors.</p></li><li><p>Prefer type-safe errors with <code>.errors(...)</code> and <code>errors.MY_ERROR(...)</code> for expected failure cases the client needs to handle.</p></li></ul><h2 id="step-4-web-data-layer" tabindex="-1">Step 4: Web Data Layer <a class="header-anchor" href="#step-4-web-data-layer" aria-label="Permalink to &quot;Step 4: Web Data Layer&quot;">​</a></h2><ul><li>Use oRPC&#39;s TanStack Query integration from <code>@saasweave/api/client/tanstack-start/orpc</code>.</li><li>Follow <a href="/SaaSWeave/develop/api-fetching-patterns">API fetching patterns</a> for <code>*.query.ts</code>, <code>*.mutation.ts</code>, query keys, query options, and hook wrappers.</li><li>Keep <code>orpc</code> and TanStack Query wiring inside slice-local <code>api/</code> files, not inline in page components.</li></ul><h2 id="step-5-client-error-handling" tabindex="-1">Step 5: Client Error Handling <a class="header-anchor" href="#step-5-client-error-handling" aria-label="Permalink to &quot;Step 5: Client Error Handling&quot;">​</a></h2><ul><li>For user-visible failure states, follow the type-safe client error pattern in <a href="/SaaSWeave/develop/orpc">oRPC patterns</a>.</li><li>Do not duplicate string-matched or ad hoc client error handling in web slices when the server already defines typed oRPC errors.</li></ul><h2 id="step-6-routes-and-ui" tabindex="-1">Step 6: Routes And UI <a class="header-anchor" href="#step-6-routes-and-ui" aria-label="Permalink to &quot;Step 6: Routes And UI&quot;">​</a></h2><ul><li>Follow <a href="/SaaSWeave/develop/tanstack-patterns">TanStack patterns</a> for route placement, thin <code>beforeLoad</code>, and page composition.</li><li>Follow <a href="/SaaSWeave/develop/ui">UI guidelines</a> for app-level component composition.</li><li>Add <a href="/SaaSWeave/develop/auth">Auth patterns</a>, <a href="/SaaSWeave/develop/seo">SEO patterns</a>, or <a href="/SaaSWeave/develop/i18n">i18n guidelines</a> when the feature touches those surfaces.</li></ul><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><ul><li>Follow <a href="/SaaSWeave/develop/workflow">Workflow</a> for fix cadence and validation scope. For larger planned work, such as implementing a <code>plan.md</code>, run fixes at substantial milestones/phases and once more before final handoff. Follow <a href="/SaaSWeave/develop/testing">Testing</a> for focused regression, unit, and e2e coverage when behavior changes.</li></ul>',22)])])}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
